import{_ as g,I as r,o as c,c as u,b6 as d,J as o}from"./chunks/framework.COUcLbTA.js";const S=JSON.parse('{"title":"数据结构","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/1-computer-fundamentals/data-structures.md","filePath":"zh-cn/appendix/1-computer-fundamentals/data-structures.md"}'),p={name:"zh-cn/appendix/1-computer-fundamentals/data-structures.md"};function _(b,t,m,O,q,T){const n=r("DataStructureOverviewDemo"),a=r("LinearStructuresDemo"),s=r("HashTableDemo"),e=r("TreeStructureDemo"),l=r("GraphStructureDemo"),i=r("DataStructureDemo"),h=r("DataStructureSelectorDemo");return c(),u("div",null,[t[0]||(t[0]=d('<h1 id="数据结构" tabindex="-1">数据结构 <a class="header-anchor" href="#数据结构" aria-label="Permalink to “数据结构”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p><strong>程序 = 数据结构 + 算法。</strong> 前面我们学了 CPU 如何执行指令、操作系统如何管理资源。但程序要处理的核心对象是<strong>数据</strong>——用户信息、商品列表、社交关系……这些数据怎么在内存里组织，直接决定了程序的快慢。你可能遇到过这样的困惑：为什么有些程序处理几万条数据很快，有些处理几百条就卡住了？答案往往就在于<strong>数据结构的选择</strong>。</p></div><p><strong>这篇文章会带你学什么？</strong></p><p>学完这章后，你将获得：</p><ul><li><strong>直觉判断力</strong>：看到一个需求，脑子里自动浮现该用什么数据结构</li><li><strong>性能分析视角</strong>：能判断性能瓶颈是数据结构选错了，还是算法效率低</li><li><strong>权衡思维</strong>：理解&quot;空间换时间&quot;与&quot;时间换空间&quot;，知道没有完美的数据结构</li><li><strong>代码阅读能力</strong>：看到 HashMap、Stack、Queue 这些词不再陌生</li><li><strong>后续学习基础</strong>：为数据库索引、缓存系统、搜索引擎等技术打下基础</li></ul><table tabindex="0"><thead><tr><th>章节</th><th>内容</th><th>核心概念</th></tr></thead><tbody><tr><td><strong>第 1 章</strong></td><td>全景图</td><td>四大类数据结构、分类标准</td></tr><tr><td><strong>第 2 章</strong></td><td>线性结构</td><td>数组、链表、栈、队列</td></tr><tr><td><strong>第 3 章</strong></td><td>哈希表</td><td>哈希函数、冲突处理、O(1) 查找</td></tr><tr><td><strong>第 4 章</strong></td><td>树形结构</td><td>二叉树、文件系统树、DOM 树</td></tr><tr><td><strong>第 5 章</strong></td><td>图结构</td><td>有向图、无向图、遍历算法</td></tr><tr><td><strong>第 6 章</strong></td><td>性能对比</td><td>时间复杂度、空间复杂度</td></tr><tr><td><strong>第 7 章</strong></td><td>选型指南</td><td>场景分析、决策流程</td></tr></tbody></table><hr><h2 id="_1-全景图-数据结构是什么" tabindex="-1">1. 全景图：数据结构是什么？ <a class="header-anchor" href="#_1-全景图-数据结构是什么" aria-label="Permalink to “1. 全景图：数据结构是什么？”">​</a></h2><p>想象你要整理一堆书：</p><ul><li><strong>堆在地上</strong>：找书要一本本翻——这就是最原始的存储</li><li><strong>按编号放书架</strong>：直接去对应位置拿——这就是<strong>数组</strong></li><li><strong>按类别分柜子</strong>：先确定柜子再找书——这就是<strong>哈希表</strong></li><li><strong>按书名排序放多层架</strong>：每次排除一半——这就是<strong>树</strong></li></ul><p>不同的整理方式，找书的效率天差地别。<strong>数据结构就是数据的&quot;整理方式&quot;</strong>——它决定了数据怎么存、怎么找、怎么改。</p>',11)),o(n),t[1]||(t[1]=d('<p>所有数据结构可以归为四大类：</p><table tabindex="0"><thead><tr><th>类型</th><th>数据关系</th><th>典型代表</th><th>生活类比</th></tr></thead><tbody><tr><td><strong>线性结构</strong></td><td>一对一，排成一排</td><td>数组、链表、栈、队列</td><td>火车车厢、排队队伍</td></tr><tr><td><strong>哈希结构</strong></td><td>键→值映射</td><td>哈希表、字典、集合</td><td>图书馆索引卡片</td></tr><tr><td><strong>树形结构</strong></td><td>一对多，层级关系</td><td>二叉树、B树、堆</td><td>家族族谱、文件夹</td></tr><tr><td><strong>图结构</strong></td><td>多对多，网状关系</td><td>有向图、无向图</td><td>地铁线路图、社交网络</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么要学这么多种？</p><p>因为<strong>没有万能的数据结构</strong>。每种结构都是在&quot;查找速度&quot;、&quot;插入速度&quot;、&quot;内存占用&quot;之间做权衡。就像你不会用书包装家具，也不会用卡车送一封信——选对工具，事半功倍。</p></div><hr><h2 id="_2-线性结构-最基础的组织方式" tabindex="-1">2. 线性结构：最基础的组织方式 <a class="header-anchor" href="#_2-线性结构-最基础的组织方式" aria-label="Permalink to “2. 线性结构：最基础的组织方式”">​</a></h2><p>线性结构是最直觉的数据组织方式——数据一个接一个排列，就像火车车厢。但&quot;怎么连接&quot;和&quot;从哪端操作&quot;的不同，产生了四种变体，各有各的绝活。</p>',6)),o(a),t[2]||(t[2]=d('<h3 id="_2-1-数组-vs-链表-两种截然不同的存储方式" tabindex="-1">2.1 数组 vs 链表：两种截然不同的存储方式 <a class="header-anchor" href="#_2-1-数组-vs-链表-两种截然不同的存储方式" aria-label="Permalink to “2.1 数组 vs 链表：两种截然不同的存储方式”">​</a></h3><p>数组和链表是最基础的两种线性结构，它们的核心区别在于<strong>内存布局</strong>：</p><table tabindex="0"><thead><tr><th>对比维度</th><th>数组</th><th>链表</th></tr></thead><tbody><tr><td><strong>内存布局</strong></td><td>连续的一整块</td><td>散落在各处，用指针串起来</td></tr><tr><td><strong>访问第 n 个</strong></td><td>直接算地址，O(1)</td><td>从头一个个找，O(n)</td></tr><tr><td><strong>中间插入</strong></td><td>后面的都要挪，O(n)</td><td>改两个指针就行，O(1)</td></tr><tr><td><strong>大小</strong></td><td>创建时就固定了</td><td>随时可以增长</td></tr><tr><td><strong>生活类比</strong></td><td>一排编号储物柜</td><td>寻宝游戏的线索链</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">什么时候用数组？什么时候用链表？</p><ul><li><strong>数据量已知、频繁按位置访问</strong> → 数组（比如学生成绩表、像素矩阵）</li><li><strong>数据量未知、频繁插入删除</strong> → 链表（比如播放列表、撤销历史）</li><li><strong>不确定？</strong> → 先用数组。大多数场景下，数组的缓存友好性带来的性能优势更大</li></ul></div><h3 id="_2-2-栈和队列-加了-规矩-的线性结构" tabindex="-1">2.2 栈和队列：加了&quot;规矩&quot;的线性结构 <a class="header-anchor" href="#_2-2-栈和队列-加了-规矩-的线性结构" aria-label="Permalink to “2.2 栈和队列：加了&quot;规矩&quot;的线性结构”">​</a></h3><p>栈和队列本质上就是数组或链表，只是<strong>限制了操作方式</strong>。看起来功能变少了，但正是这种限制让它们有了明确的用途：</p><table tabindex="0"><thead><tr><th>结构</th><th>规则</th><th>操作</th><th>类比</th><th>你写的代码里在哪？</th></tr></thead><tbody><tr><td><strong>栈</strong></td><td>后进先出 (LIFO)</td><td>push / pop</td><td>一摞盘子</td><td>函数调用栈、浏览器后退、Ctrl+Z 撤销</td></tr><tr><td><strong>队列</strong></td><td>先进先出 (FIFO)</td><td>enqueue / dequeue</td><td>排队买票</td><td>任务调度、消息队列、打印队列</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么&quot;限制&quot;反而是好事？</p><p>想象一个只有&quot;放盘子&quot;和&quot;拿盘子&quot;两个操作的栈——你永远不会拿错顺序。<strong>限制带来确定性，确定性带来可靠性。</strong> 函数调用栈就是靠&quot;后进先出&quot;保证最后调用的函数最先返回，如果允许随意访问中间的函数，程序就乱套了。</p></div><hr><h2 id="_3-哈希表-最快的查找" tabindex="-1">3. 哈希表：最快的查找 <a class="header-anchor" href="#_3-哈希表-最快的查找" aria-label="Permalink to “3. 哈希表：最快的查找”">​</a></h2><p>线性结构的查找都不够快——数组要遍历 O(n)，即使排好序用二分查找也要 O(log n)。有没有一种结构能做到 <strong>O(1) 直接找到</strong>？有，就是哈希表。</p>',11)),o(s),t[3]||(t[3]=d('<h3 id="_3-1-哈希表的核心思想" tabindex="-1">3.1 哈希表的核心思想 <a class="header-anchor" href="#_3-1-哈希表的核心思想" aria-label="Permalink to “3.1 哈希表的核心思想”">​</a></h3><p>哈希表的原理其实很简单：</p><ol><li>你给一个<strong>键</strong>（比如 &quot;apple&quot;）</li><li><strong>哈希函数</strong>把键算成一个数字（比如 <code>hash(&quot;apple&quot;) = 3</code>）</li><li>直接去数组的第 3 个位置找——不用遍历，一步到位</li></ol><p>这就像图书馆的索引系统：你不用在一排排书架上找，查索引卡片就能直接定位到书的位置。</p><h3 id="_3-2-哈希冲突-两个键撞车了怎么办" tabindex="-1">3.2 哈希冲突：两个键撞车了怎么办？ <a class="header-anchor" href="#_3-2-哈希冲突-两个键撞车了怎么办" aria-label="Permalink to “3.2 哈希冲突：两个键撞车了怎么办？”">​</a></h3><p>两个不同的键可能算出同一个索引——这叫<strong>哈希冲突</strong>。就像两本书的索引号相同，都指向同一个位置。</p><table tabindex="0"><thead><tr><th>解决方法</th><th>原理</th><th>类比</th></tr></thead><tbody><tr><td><strong>链地址法</strong></td><td>同一位置用链表存多个值</td><td>同一个柜子里放多本书</td></tr><tr><td><strong>开放寻址法</strong></td><td>冲突了就往后找空位</td><td>柜子满了就放隔壁柜子</td></tr></tbody></table><h3 id="_3-3-哈希表的性能" tabindex="-1">3.3 哈希表的性能 <a class="header-anchor" href="#_3-3-哈希表的性能" aria-label="Permalink to “3.3 哈希表的性能”">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>平均情况</th><th>最坏情况（全部冲突）</th></tr></thead><tbody><tr><td><strong>查找</strong></td><td>O(1)</td><td>O(n)</td></tr><tr><td><strong>插入</strong></td><td>O(1)</td><td>O(n)</td></tr><tr><td><strong>删除</strong></td><td>O(1)</td><td>O(n)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">什么时候会退化？</p><p>当所有键都映射到同一个索引时，哈希表退化为链表，所有操作变成 O(n)。避免方法：选择好的哈希函数 + 动态扩容（负载因子超过阈值时扩容）。</p></div><div class="tip custom-block"><p class="custom-block-title">哈希表在你的代码里无处不在</p><ul><li>JavaScript 的 <code>{}</code> 对象和 <code>Map</code> → 哈希表</li><li>Python 的 <code>dict</code> → 哈希表</li><li>Java 的 <code>HashMap</code> → 哈希表</li><li>数据库的索引 → 底层也用哈希</li></ul><p>你每次写 <code>user[&quot;name&quot;]</code> 或 <code>map.get(&quot;key&quot;)</code>，背后都是哈希表在工作。</p></div><hr><h2 id="_4-树形结构-层级关系的表达" tabindex="-1">4. 树形结构：层级关系的表达 <a class="header-anchor" href="#_4-树形结构-层级关系的表达" aria-label="Permalink to “4. 树形结构：层级关系的表达”">​</a></h2><p>哈希表查找快，但数据是无序的。如果你需要<strong>既能快速查找，又能保持数据有序</strong>，就需要树形结构了。</p><p>树的核心特征：每个节点可以有多个&quot;孩子&quot;，但只有一个&quot;父亲&quot;（根节点除外）。这种一对多的层级关系，在现实中随处可见。</p>',15)),o(e),t[4]||(t[4]=d('<h3 id="_4-1-二叉搜索树-有序的树" tabindex="-1">4.1 二叉搜索树：有序的树 <a class="header-anchor" href="#_4-1-二叉搜索树-有序的树" aria-label="Permalink to “4.1 二叉搜索树：有序的树”">​</a></h3><p>二叉搜索树有一个简单但强大的规则：<strong>左小右大</strong>。</p><ul><li>左子树的所有值 &lt; 根节点</li><li>右子树的所有值 &gt; 根节点</li></ul><p>查找时，每次比较都能排除一半节点，时间复杂度 O(log n)。就像猜数字游戏——&quot;比 50 大还是小？&quot;&quot;大。&quot;&quot;比 75 大还是小？&quot;——每次排除一半。</p><h3 id="_4-2-平衡树-防止退化" tabindex="-1">4.2 平衡树：防止退化 <a class="header-anchor" href="#_4-2-平衡树-防止退化" aria-label="Permalink to “4.2 平衡树：防止退化”">​</a></h3><p>二叉搜索树有个问题：如果数据按顺序插入（1, 2, 3, 4, 5），树会退化成一条链，查找变回 O(n)。平衡树通过自动调整结构来避免这个问题：</p><table tabindex="0"><thead><tr><th>类型</th><th>平衡策略</th><th>特点</th><th>典型应用</th></tr></thead><tbody><tr><td><strong>AVL 树</strong></td><td>严格平衡（高度差 ≤ 1）</td><td>查找最快，插入删除稍慢</td><td>需要频繁查找的场景</td></tr><tr><td><strong>红黑树</strong></td><td>近似平衡</td><td>综合性能好</td><td>Java TreeMap、Linux 内核</td></tr><tr><td><strong>B 树</strong></td><td>多路平衡，一个节点存多个值</td><td>减少磁盘 I/O</td><td>数据库索引</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">树在你的代码里在哪？</p><ul><li><strong>文件系统</strong>：文件夹嵌套就是树结构</li><li><strong>HTML DOM</strong>：<code>&lt;html&gt;</code> → <code>&lt;body&gt;</code> → <code>&lt;div&gt;</code> → <code>&lt;p&gt;</code> 就是一棵树</li><li><strong>数据库索引</strong>：B+ 树让百万级数据的查找只需要 3-4 次磁盘读取</li><li><strong>JSON/XML</strong>：嵌套的数据格式本质上就是树</li></ul></div><hr><h2 id="_5-图结构-复杂关系的网络" tabindex="-1">5. 图结构：复杂关系的网络 <a class="header-anchor" href="#_5-图结构-复杂关系的网络" aria-label="Permalink to “5. 图结构：复杂关系的网络”">​</a></h2><p>树只能表示&quot;一对多&quot;的层级关系。但现实中很多关系是&quot;多对多&quot;的——你的朋友也有朋友，城市之间有多条路可以走。这种<strong>任意节点之间都可能有连接</strong>的结构，就是图。</p>',11)),o(l),t[5]||(t[5]=d('<h3 id="_5-1-图的三种形态" tabindex="-1">5.1 图的三种形态 <a class="header-anchor" href="#_5-1-图的三种形态" aria-label="Permalink to “5.1 图的三种形态”">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>类比</th><th>典型应用</th></tr></thead><tbody><tr><td><strong>无向图</strong></td><td>边没有方向，A→B 等于 B→A</td><td>微信好友（互相的）</td><td>社交网络、通信网络</td></tr><tr><td><strong>有向图</strong></td><td>边有方向，A→B 不等于 B→A</td><td>微博关注（单向的）</td><td>网页链接、依赖关系</td></tr><tr><td><strong>带权图</strong></td><td>边有权重（距离、费用等）</td><td>城市间的公路（有里程数）</td><td>地图导航、最短路径</td></tr></tbody></table><h3 id="_5-2-图的遍历" tabindex="-1">5.2 图的遍历 <a class="header-anchor" href="#_5-2-图的遍历" aria-label="Permalink to “5.2 图的遍历”">​</a></h3><p>图的遍历比线性结构复杂，因为可能有环（A→B→C→A），需要记录&quot;已访问&quot;的节点：</p><table tabindex="0"><thead><tr><th>遍历方式</th><th>策略</th><th>类比</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>BFS（广度优先）</strong></td><td>先访问所有邻居，再访问邻居的邻居</td><td>水波纹扩散</td><td>最短路径、层级遍历</td></tr><tr><td><strong>DFS（深度优先）</strong></td><td>一条路走到底，走不通再回头</td><td>走迷宫</td><td>路径搜索、连通性判断</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">图在现实中的应用</p><ul><li><strong>地图导航</strong>：城市是节点，道路是边，导航就是在图上找最短路径</li><li><strong>社交网络</strong>：用户是节点，关注/好友是边，&quot;你可能认识的人&quot;就是图算法推荐的</li><li><strong>包管理器</strong>：npm/pip 的依赖关系就是有向图，<code>npm install</code> 就是在做图的拓扑排序</li></ul></div><hr><h2 id="_6-性能对比-一张表看清所有数据结构" tabindex="-1">6. 性能对比：一张表看清所有数据结构 <a class="header-anchor" href="#_6-性能对比-一张表看清所有数据结构" aria-label="Permalink to “6. 性能对比：一张表看清所有数据结构”">​</a></h2><p>学了这么多数据结构，它们的性能到底差多少？下面这个交互式对比能帮你建立直觉：</p>',9)),o(i),t[6]||(t[6]=d('<p><strong>核心性能对比表：</strong></p><table tabindex="0"><thead><tr><th>数据结构</th><th>访问</th><th>查找</th><th>插入</th><th>删除</th><th>空间</th></tr></thead><tbody><tr><td><strong>数组</strong></td><td>O(1)</td><td>O(n)</td><td>O(n)</td><td>O(n)</td><td>O(n)</td></tr><tr><td><strong>链表</strong></td><td>O(n)</td><td>O(n)</td><td>O(1)</td><td>O(1)</td><td>O(n)</td></tr><tr><td><strong>栈/队列</strong></td><td>O(n)</td><td>O(n)</td><td>O(1)</td><td>O(1)</td><td>O(n)</td></tr><tr><td><strong>哈希表</strong></td><td>—</td><td>O(1)</td><td>O(1)</td><td>O(1)</td><td>O(n)</td></tr><tr><td><strong>二叉搜索树</strong></td><td>—</td><td>O(log n)</td><td>O(log n)</td><td>O(log n)</td><td>O(n)</td></tr><tr><td><strong>图</strong></td><td>—</td><td>O(V+E)</td><td>O(1)</td><td>O(E)</td><td>O(V+E)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">怎么读这张表？</p><ul><li><strong>O(1)</strong>：不管数据量多大，操作时间恒定——最快</li><li><strong>O(log n)</strong>：数据量翻倍，时间只多一步——很快</li><li><strong>O(n)</strong>：数据量翻倍，时间也翻倍——一般</li><li><strong>O(V+E)</strong>：取决于节点数和边数——图的特殊表示</li></ul><p>注意：这些都是<strong>平均情况</strong>。最坏情况下，哈希表会退化到 O(n)，二叉搜索树也会退化到 O(n)。</p></div><hr><h2 id="_7-选型指南-该用哪种数据结构" tabindex="-1">7. 选型指南：该用哪种数据结构？ <a class="header-anchor" href="#_7-选型指南-该用哪种数据结构" aria-label="Permalink to “7. 选型指南：该用哪种数据结构？”">​</a></h2><p>学了这么多数据结构，面对实际需求时该怎么选？关键是<strong>从需求出发</strong>，问自己几个问题：</p><ol><li><strong>最频繁的操作是什么？</strong> 查找？插入？删除？遍历？</li><li><strong>数据之间有什么关系？</strong> 一对一？一对多？多对多？</li><li><strong>数据量有多大？</strong> 几十条和几百万条的最优选择可能完全不同</li><li><strong>需要有序吗？</strong> 是否需要按某种顺序遍历数据</li></ol>',7)),o(h),t[7]||(t[7]=d('<p><strong>快速决策流程：</strong></p><table tabindex="0"><thead><tr><th>你的需求</th><th>推荐结构</th><th>原因</th></tr></thead><tbody><tr><td>按位置快速访问</td><td>数组</td><td>O(1) 随机访问</td></tr><tr><td>频繁在中间插入删除</td><td>链表</td><td>O(1) 插入删除，不用移动元素</td></tr><tr><td>后进先出（撤销、递归）</td><td>栈</td><td>LIFO 语义天然匹配</td></tr><tr><td>先进先出（任务队列）</td><td>队列</td><td>FIFO 语义天然匹配</td></tr><tr><td>按键快速查找</td><td>哈希表</td><td>O(1) 平均查找</td></tr><tr><td>有序数据 + 快速查找</td><td>二叉搜索树</td><td>O(log n) 查找且保持有序</td></tr><tr><td>复杂多对多关系</td><td>图</td><td>能表达任意节点间的连接</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">实际开发中的经验法则</p><ul><li><strong>80% 的场景</strong>用数组和哈希表就够了</li><li><strong>需要有序</strong>时考虑树</li><li><strong>关系复杂</strong>时考虑图</li><li><strong>不确定？</strong> 先用最简单的，遇到性能问题再换。过早优化是万恶之源</li></ul></div><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><blockquote><p>数据结构是程序的骨架。<strong>数组</strong>像一排编号储物柜，按位置取东西最快；<strong>链表</strong>像寻宝线索链，插入删除最灵活；<strong>哈希表</strong>像图书馆索引，按名字找东西最快；<strong>树</strong>像家族族谱，表达层级关系且保持有序；<strong>图</strong>像地铁线路图，表达任意复杂的网状关系。没有最好的数据结构，只有最合适的——关键是理解每种结构的优势和代价，根据实际需求做出权衡。</p></blockquote><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>推荐资源</th></tr></thead><tbody><tr><td>数据结构可视化</td><td><a href="https://visualgo.net/" target="_blank" rel="noreferrer">VisuAlgo</a> - 动画演示各种数据结构和算法</td></tr><tr><td>算法与数据结构</td><td>《算法图解》- Aditya Bhargava，图文并茂适合入门</td></tr><tr><td>深入理解</td><td>《数据结构与算法分析》- Mark Allen Weiss</td></tr><tr><td>刷题练习</td><td><a href="https://leetcode.cn/" target="_blank" rel="noreferrer">LeetCode</a> - 按数据结构分类练习</td></tr></tbody></table><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><p>现在你已经掌握了数据结构的核心知识。接下来可以继续学习：</p><ul><li><strong><a href="./algorithm-thinking.html">算法思维</a></strong>：学会用排序、搜索、递归、动态规划等算法思维解决问题</li><li><strong><a href="./programming-languages.html">编程语言</a></strong>：了解不同编程语言如何实现这些数据结构</li></ul>',13))])}const P=g(p,[["render",_]]);export{S as __pageData,P as default};
